function setupGame(id){state.screen=id;{const cf=PLAY_CFG();state.unlockedGame=null;state.gate=cf.mode==='unlock'&&!NON_GAMES.includes(id)?{id,n:0,need:Math.max(1,Number(cf.words)||5)}:null}state.lastGame=id;save();state.notice='';state.challenge=null;if(id==='connect')state.game={board:Array.from({length:6},()=>Array(7).fill(0)),turn:1,winner:0,moves:0};if(id==='memory'){const picks=shuffle([...MUSHROOMS,...FLOWERS]).slice(0,8);state.game={cards:shuffle(picks.flatMap((key,i)=>[{key,id:i},{key,id:i}])),revealed:[],matched:[],moves:0,pending:false}};if(id==='dam')state.game={placed:Array(12).fill(null),selected:0,earned:0};if(id==='garden')state.game={placed:Array(15).fill(null),selected:0,earned:0};if(id==='pond')state.game={placed:[],selected:0,earned:0};if(id==='tictactoe')state.game={board:Array(9).fill(0),winner:0,turn:1};if(id==='acorn')state.game=makeAcorn();if(id==='root')state.game=makeRoot();if(id==='solitaire')state.game=makeSolitaire();if(id==='test')state.game={phase:'pick'};if(id==='learn')state.game={phase:'pick'};if(id==='review')state.game={phase:'intro'};state.pendingIntro=null;state.intro=null;if(state.pendingIntro===id){state.pendingIntro=null;state.tour=null;state.intro=id;if(id!=='solitaire')say(GUIDES[id].hello,GUIDES[id].who)}render()}
function gameHTML(){let info=GAME_INFO.find(g=>g[0]===state.screen);if(state.screen==='solitaire')return `<div class="game-wrap sc-focus">${solitaireHTML()}</div>`;if(state.screen==='memory')return `<div class="game-wrap sc-focus">${memoryHTML()}</div>`;if(state.screen==='learn')return `<div class="game-wrap sc-focus">${learnHTML()}</div>`;if(['garden','dam','pond'].includes(state.screen))return `<div class="game-wrap sc-focus">${({garden:gardenHTML,dam:damHTML,pond:pondHTML})[state.screen]()}</div>`;return `<div class="game-wrap sc-focus"><div class="sc-bar bx-bar"><button class="sc-round" data-act="home" aria-label="All games"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 21v-8a1 1 0 0 0-1-1h-4a1 1 0 0 0-1 1v8"/><path d="M3 10a2 2 0 0 1 .709-1.528l7-5.999a2 2 0 0 1 2.582 0l7 5.999A2 2 0 0 1 21 10v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/></svg></button><button class="sc-round ${state.volume?'':'off'}" data-act="toggle-volume" aria-label="${state.volume?'Turn sound off':'Turn sound on'}">${ICON_SPEAK}</button>${state.notice?`<div role="status" aria-live="polite" class="sc-notice">${esc(state.notice)}</div>`:''}<button class="btn btn-ghost sc-big mm-new" data-act="tour-start">How to play?</button>${['test','review'].includes(state.screen)?'':'<button class="btn btn-ghost sc-big" data-act="new-game">New game</button>'}</div>${({connect:connectHTML,solitaire:solitaireHTML,memory:memoryHTML,dam:damHTML,garden:gardenHTML,pond:pondHTML,tictactoe:tttHTML,acorn:acornHTML,root:rootHTML,test:testHTML,learn:learnHTML,review:reviewHTML})[state.screen]()} </div>`}
/* LITERACY ENGINE: progress, review scheduling, word sources */
const REVIEW_STEPS=[10*60e3,864e5,3*864e5,7*864e5,14*864e5];
const prog=w=>state.progress[w]||(state.progress[w]={taught:false,ind:0,sup:0,modeled:0,attempts:0,hints:0,patterns:[],last:0,next:0,step:0});
function recordResult(word,r){const p=prog(word),now=Date.now();p.attempts+=r.attempts||1;p.hints+=r.hints||0;p.last=now;
if(r.ok===false){p.step=0;p.next=now+REVIEW_STEPS[0]}
else if(r.modeled){p.modeled++;p.step=0;p.next=now+REVIEW_STEPS[0]}
else if(r.independent){p.ind++;p.step=Math.min(p.step+1,REVIEW_STEPS.length-1);p.next=now+REVIEW_STEPS[p.step]}
else{p.sup++;p.step=Math.max(0,p.step-1);p.next=now+REVIEW_STEPS[0]}
if(r.mode==='learn')p.taught=true;save()}
function notePattern(word){const m=LIT.meta(word),p=prog(word);if(m.pattern&&!p.patterns.includes(m.pattern))p.patterns.push(m.pattern)}
const ALL_WORDS=()=>[...new Set(Object.values(GROUPS).flat())];
const isDue=w=>{const p=state.progress[w];return !!(p&&p.next&&p.next<=Date.now())};
const needsReview=w=>{const p=state.progress[w];return !!(p&&(isDue(w)||p.sup+p.modeled>p.ind||p.patterns.length))};
const isLearned=w=>{const p=state.progress[w];return !!(p&&(p.taught||p.ind))};
const canExplain=m=>!!m.pattern&&(!m.needsApproval||!!state.approved[m.pattern]);
function sourceWords(){const g=state.group,src=state.source||'group';let l;if(src==='marked')l=MARKED;else if(src==='review')l=ALL_WORDS().filter(needsReview);else if(src==='learned')l=ALL_WORDS().filter(isLearned);else l=state.priority&&g==='2A'?MARKED:GROUPS[g];return l&&l.length?l:GROUPS[g]}
const SOURCE_NAMES={group:'Selected group',marked:'Marked 2A words',review:'Words needing review',learned:'All learned words'};
function nextWord(){const list=sourceWords();const due=list.filter(isDue);if(due.length&&Math.random()<.6)return due[randint(due.length)];const key='src:'+(state.source||'group')+':'+state.group;const i=(state.next[key]||0)%list.length;state.next[key]=(state.next[key]||0)+1;save();return list[i]}

function startSpell(onSuccess){if(state.challenge)return;if(state.freePlay){onSuccess();render();return}startSpellWord(nextWord(),onSuccess,{mode:'play'})}
function startSpellWord(word,onSuccess,opts={}){const real=[...word].map(char=>({char,real:true}));const extra=shuffle('abcdefghijklmnopqrstuvwxyz'.split('').filter(c=>!word.includes(c))).slice(0,word.length<5?2:3).map(char=>({char,real:false}));const tiles=shuffle(real.concat(extra)).map((t,id)=>({...t,id}));state.challenge={word,tiles,placed:Array(word.length).fill(null),order:[],errors:0,attempts:0,hint:0,wrong:[],feedback:'',modeled:false,solved:false,onSuccess,mode:opts.mode||'play',continueLabel:opts.continueLabel||'Make my move →'};render();say(word);setTimeout(()=>neuralPrefetch(),50);setTimeout(()=>{const c=state.challenge;if(c&&c.word===word&&!c.order.length&&!c.heardOnce&&!(window.speechSynthesis&&speechSynthesis.speaking)&&!(neural.audio&&!neural.audio.paused)){c.heardOnce=true;say(word)}},1400)}

const PICTURE_CLUES={"saw":"🪚","home":"🏠","box":"📦","stand":"🧍","first":"🥇","girl":"👧","house":"🏡","find":"🔍","book":"📕","look":"👀","mother":"👩‍👧","run":"🏃","school":"🏫","people":"👨‍👩‍👧‍👦","night":"🌙","say":"🗣️","think":"🤔","big":"🐘","ball":"⚽","morning":"🌅","four":"4️⃣","color":"🎨","red":"🟥","friend":"🤝","pretty":"🌸","eat":"🍽️","year":"📅","white":"⬜","play":"🧸","wish":"🌠","black":"⬛","hand":"✋","tree":"🌳","present":"🎁","name":"📛","please":"🙏","right":"➡️","next":"⏭️","under":"⬇️","best":"🏆","more":"➕","why":"❓","tell":"💬","five":"5️⃣","read":"📖","ran":"🏃‍♀️","high":"⬆️","open":"📭","call":"📞","sure":"👍","kind":"💝","end":"🏁","far":"🔭","near":"📍","both":"👯","over":"🌈","dear":"💌","men":"👨‍👨‍👦","bring":"🎒"};
const SP_ICONS={undo:'<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 14 4 9l5-5"/><path d="M4 9h10.5a5.5 5.5 0 0 1 0 11H11"/></svg>',erase:'<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m7 21-4.3-4.3c-1-1-1-2.5 0-3.4l9.6-9.6c1-1 2.5-1 3.4 0l5.6 5.6c1 1 1 2.5 0 3.4L13 21"/><path d="M22 21H7"/><path d="m5 11 9 9"/></svg>',bulb:'<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 14c.2-1 .7-1.7 1.5-2.5 1-.9 1.5-2.2 1.5-3.5A6 6 0 0 0 6 8c0 1 .2 2.2 1.5 3.5.7.7 1.3 1.5 1.5 2.5"/><path d="M9 18h6"/><path d="M10 22h4"/></svg>',big:'<svg width="54" height="54" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M11 4.702a.705.705 0 0 0-1.203-.498L6.413 7.587A1.4 1.4 0 0 1 5.416 8H3a1 1 0 0 0-1 1v6a1 1 0 0 0 1 1h2.416a1.4 1.4 0 0 1 .997.413l3.383 3.384A.705.705 0 0 0 11 19.298z"/><path d="M16 9a5 5 0 0 1 0 6"/><path d="M19.364 18.364a9 9 0 0 0 0-12.728"/></svg>'};
const HINT_MSG=['Listen, then tap the letters in order.','Listen to the word again.','Listen slowly.','Each glowing group is one part of the word.','The glowing boxes are the tricky part. Extra letters are gone.','Watch, then build it with the letters shown.'];
function challengeHTML(){const c=state.challenge,w=c.word,m=LIT.meta(w);const filled=c.placed.filter(Boolean).length,next=c.placed.indexOf(null);if(!c.shown)requestAnimationFrame(()=>{c.shown=true});
const msg=c.solved?(c.modeled?'You built it with help. Great work!':c.hint>=3||c.errors?'You did it!':'You spelled it all by yourself!'):c.feedback||HINT_MSG[c.hint];
const boxes=[...w].map((ch,i)=>{const p=c.placed[i],L=m.letters[i];const cls=['letter-box','sp-box',p?'filled':'',p&&c.justAdded&&c.order[c.order.length-1]===i?'pop':'',i===next&&!c.solved?'next':'',c.wrong.includes(i)?'oops':'',c.hint>=3&&!c.solved?'grp'+(L.start?' gs':'')+(L.end?' ge':''):'',c.hint>=4&&L.focus&&!c.solved?'focus':'',c.modeled&&!p?'soft':''].join(' ');return `<button class="${cls}" data-act="remove-letter" data-idx="${i}" aria-label="${p?'Remove letter '+p.char:'Empty letter space'}">${p?p.char.toUpperCase():c.modeled?ch.toUpperCase():''}</button>`}).join('');
const tiles=c.tiles.filter(t=>c.hint<4||t.real);
const gate=state.gate&&state.gate.id===state.screen?state.gate:null;if(gate&&!gate.seenBar)setTimeout(()=>{gate.seenBar=true},3000);return `<div class="overlay sp-overlay" role="dialog" aria-modal="true" aria-label="Spelling challenge">${gate?`<div class="gate-bar ${gate.n>0||gate.seenBar?'mini':''}" aria-label="Word ${gate.n+1} of ${gate.need} to unlock the game"><b>Spell ${gate.need} words to play!</b><span class="gate-acorns">${Array.from({length:gate.need},(_,i)=>`<i class="${i<gate.n?'on':i===gate.n?'now':''}"><img src="${ASSETS.token_acorn}" alt=""></i>`).join('')}</span></div>`:''}<div class="spell-panel sp-panel ${c.solved?'solved':''} ${c.shown?'still':''}">
<p class="sp-msg" role="status" aria-live="polite">${esc(msg)}</p>
${c.solved?'':`<div class="sp-clues"><button class="sp-hear" data-act="speak" aria-label="Hear the word"><span class="sp-hear-btn">${SP_ICONS.big}</span><span class="sp-hear-label">Hear the word</span></button><button class="sp-hear sp-slow" data-act="speak-slow" aria-label="Hear the word slowly"><span class="sp-slow-btn">${SP_ICONS.big}</span><span class="sp-hear-label">Slow</span></button>${PICTURE_CLUES[w]?`<button class="sp-hear sp-pic" data-act="speak" aria-label="Picture clue. Tap to hear the word"><span class="sp-pic-img" aria-hidden="true">${PICTURE_CLUES[w]}</span><span class="sp-hear-label">Clue</span></button>`:''}</div>`}
${c.modeled&&!c.solved?`<p class="sp-model" aria-label="The word split into sounds">${m.graphemes.map((g,i)=>`<span class="${m.focus[i]?'f':''}">${esc(g)}</span>`).join('<i>|</i>')}</p>`:''}
<div class="letter-boxes sp-boxes">${boxes}</div>
${c.solved?'':`<div class="sp-edit"><button class="sp-tool sp-big-tool" data-act="spell-undo" ${filled?'':'disabled'} aria-label="Undo last letter">${SP_ICONS.undo}Undo</button><button class="sp-tool sp-big-tool" data-act="spell-clear" ${filled?'':'disabled'} aria-label="Clear all letters">${SP_ICONS.erase}Clear</button></div>`}
${c.solved?`<button class="btn btn-primary sp-go" data-act="spell-continue">${esc(c.continueLabel)}</button>`:`<div class="letter-bank sp-bank">${tiles.map(t=>`<button class="letter-tile sp-tile" data-act="add-letter" data-idx="${t.id}" ${c.placed.some(p=>p&&p.id===t.id)?'disabled':''} aria-label="Letter ${t.char.toUpperCase()}">${t.char.toUpperCase()}</button>`).join('')}</div>`}
${c.solved?'':`<button class="sp-tool sp-tool-help" data-act="spell-hint" ${c.hint>=5?'disabled':''}>${SP_ICONS.bulb}${c.hint?'More help ('+c.hint+'/5)':'Help me'}</button>`}<p class="sp-note">Try as many times as you like. Help never costs a turn.</p></div></div>`}
function checkSpelling(){const c=state.challenge;if(!c||c.placed.some(p=>!p))return;const attempt=c.placed.map(t=>t.char).join('');c.attempts++;const k=state.group+':'+c.word;state.attempt[k]=(state.attempt[k]||0)+1;
if(attempt===c.word){c.solved=true;c.wrong=[];c.feedback='';const independent=!c.modeled&&c.hint<=2&&!c.errors;state.learned[k]=(state.learned[k]||0)+1;state.completions++;recordResult(c.word,{independent,hints:c.hint,attempts:c.attempts,modeled:c.modeled,mode:c.mode});save();say((independent?'Great work! You spelled ':'You did it! ')+c.word+'.');if(window.playYay)try{playYay()}catch{}}
else{c.errors++;const a=LIT.analyze(c.word,attempt);c.wrong=a.wrong;c.feedback=a.msg;if(a.cat==='pattern')notePattern(c.word);save();say(a.msg)}render()}

function spellContinue(){let c=state.challenge;if(!c||!c.solved)return;let cb=c.onSuccess;state.challenge=null;cb();render()}
function runHint(c){const w=c.word,m=LIT.meta(w);c.feedback='';
if(c.hint===1)say(w+'. '+w);
else if(c.hint===2)saySlow(w);
else if(c.hint===3)say('Listen to '+w+' again. Each glowing group is one part of the word.'+(m.pattern==='vce'?' The e at the end is quiet.':''));
else if(c.hint===4)say('The glowing boxes are the tricky part. I took away the extra letters.');
else if(c.hint===5){c.modeled=true;c.placed=Array(w.length).fill(null);c.order=[];c.wrong=[];say('Watch. '+w+' is spelled '+w.split('').join(', ')+'. '+(canExplain(m)?m.explain+' ':'')+'Now you build it.')}}
function spellAction(action,id){const c=state.challenge;if(!c)return;c.justAdded=action==='add-letter';
if(action==='speak'){say(c.word);return}
if(action==='speak-slow'){saySlow(c.word);return}
if(c.solved){if(action==='spell-continue')spellContinue();return}
if(action==='add-letter'){const slot=c.placed.indexOf(null);if(slot<0)return;const t=c.tiles.find(t=>t.id===Number(id));if(t&&!c.placed.some(p=>p&&p.id===t.id)){c.placed[slot]=t;c.order.push(slot);c.wrong=c.wrong.filter(i=>i!==slot);checkSpelling();render()}return}
if(action==='remove-letter'){const i=Number(id);if(c.placed[i]){c.placed[i]=null;c.order=c.order.filter(x=>x!==i);c.wrong=c.wrong.filter(x=>x!==i)}}
if(action==='spell-undo'){const i=c.order.pop();if(i!=null){c.placed[i]=null;c.wrong=c.wrong.filter(x=>x!==i)}}
if(action==='spell-clear'){c.placed=Array(c.word.length).fill(null);c.order=[];c.wrong=[];c.feedback=''}
if(action==='spell-hint'&&c.hint<5){c.hint++;runHint(c)}
render()}

/* CONNECT FOUR — standard 7 columns × 6 rows with legal gravity, blocking AI, win detection. */
function connectWin(b,p){const dirs=[[0,1],[1,0],[1,1],[1,-1]];for(let r=0;r<6;r++)for(let col=0;col<7;col++)if(b[r][col]===p)for(const [dr,dc] of dirs){if(Array.from({length:4},(_,i)=>[r+dr*i,col+dc*i]).every(([rr,cc])=>rr>=0&&rr<6&&cc>=0&&cc<7&&b[rr][cc]===p))return true}return false}
function dropRow(b,col,p){for(let r=5;r>=0;r--)if(b[r][col]===0){b[r][col]=p;return r}return -1}
function drop(b,col,p){for(let r=5;r>=0;r--)if(b[r][col]===0){b[r][col]=p;return true}return false}
function simulate(b,col,p){const c=b.map(r=>r.slice());return drop(c,col,p)&&connectWin(c,p)}
function connectHTML(){const g=state.game;let ended=g.winner!==0;return `<div class="board-layout"><div><div class="board-columns">${Array.from({length:7},(_,i)=>`<button class="column-btn" data-act="connect-move" data-idx="${i}" ${ended||g.thinking||g.board[0][i]?'disabled':''} aria-label="Drop in column ${i+1}">↓</button>`).join('')}</div><div class="connect-frame" style="--woodboard:url('${ASSETS.connect_board}')"><div class="connect-grid">${g.board.flatMap((row,r)=>row.map((v,col)=>`<button class="connect-cell" data-act="connect-move" data-idx="${col}" aria-label="Row ${r+1} column ${col+1}${v?', occupied':''}" ${ended||g.thinking||g.board[0][col]?'disabled':''}>${v?img(v===1?'token_acorn':'token_leaf',g.last&&g.last[0]===r&&g.last[1]===col?'drop-in':''):''}</button>`)).join('')}</div></div></div><div class="board-side">${g.winner===2?img('beaver_wave','opp-pose win'):g.winner===1?img('beaver_sleep','opp-pose lose'):g.winner===3?img('beaver_wave','opp-pose'):g.thinking?img('beaver','opp-pose think'):img('beaver','opp-pose wait')}<h2>${g.winner===1?'🏆 You connected four!':g.winner===2?'Beaver connected four!':g.winner===3?'A friendly draw!':g.thinking?'Beaver is thinking…':'Your turn!'}</h2><p class="subtext">You are acorns. Beaver plays leaves. Spell a word, then pick a column.</p>${ended?'<button class="big-action" data-act="new-game">Play again</button>':g.thinking?'':'<p class="status-tag">Choose a column ↑</p>'}</div></div>`}
function aiConnect(){let g=state.game;if(g.winner)return;let legal=Array.from({length:7},(_,i)=>i).filter(i=>!g.board[0][i]);if(!legal.length){g.winner=3;return}let choice=legal.find(i=>simulate(g.board,i,2));if(choice===undefined)choice=legal.find(i=>simulate(g.board,i,1));if(choice===undefined)choice=shuffle(legal).sort((a,b)=>Math.abs(a-3)-Math.abs(b-3))[0];g.last=[dropRow(g.board,choice,2),choice];g.moves++;if(connectWin(g.board,2)){g.winner=2;state.notice='Beaver found four in a row. Want a rematch?'}else if(g.moves===42){g.winner=3;state.notice='A draw! You played together beautifully.'}else state.notice='Beaver played a leaf. Your turn!'}
function connectMove(col){let g=state.game;if(g.winner||g.thinking||g.board[0][col])return;startSpell(()=>{g.last=[dropRow(g.board,col,1),col];g.moves++;if(connectWin(g.board,1)){g.winner=1;state.notice='Four in a row! You won!'}else if(g.moves===42){g.winner=3;state.notice='You filled the board together!'}else{g.thinking=true;state.notice='Beaver is thinking…';setTimeout(()=>{if(state.game!==g)return;g.thinking=false;aiConnect();render()},1300)}})}
/* MEMORY */
function memoryHTML(){let g=state.game;const pairs=g.matched.length/2,done=g.matched.length===16;const fresh=g.fresh||[];g.fresh=[];
return `<div class="mm"><div class="sc-bar mm-bar"><button class="sc-round" data-act="home" aria-label="All games"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 21v-8a1 1 0 0 0-1-1h-4a1 1 0 0 0-1 1v8"/><path d="M3 10a2 2 0 0 1 .709-1.528l7-5.999a2 2 0 0 1 2.582 0l7 5.999A2 2 0 0 1 21 10v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/></svg></button><button class="sc-round ${state.volume?'':'off'}" data-act="toggle-volume" aria-label="${state.volume?'Turn sound off':'Turn sound on'}">${ICON_SPEAK}</button><div class="mm-pairs" aria-label="${pairs} of 8 pairs found"><span class="mm-pairs-n">${pairs}</span><span class="mm-pairs-l">/ 8 pairs</span></div>${state.notice?`<div role="status" aria-live="polite" class="sc-notice">${esc(state.notice)}</div>`:''}<button class="btn btn-ghost sc-big mm-new" data-act="new-game">New game</button></div>
<div class="mem-grid mm-grid">${g.cards.map((card,i)=>{const up=g.revealed.includes(i)||g.matched.includes(i),mt=g.matched.includes(i);return `<button class="mm-card ${up?'up':''} ${mt?'matched':''} ${fresh.includes(i)?'flip':''}" data-act="memory-flip" data-idx="${i}" ${mt?'disabled':''} aria-label="${up?'Card showing '+esc(card.key.replace(/^\d+_/,'').replace(/_/g,' ')):'Face-down card '+(i+1)}"><span class="mm-inner"><span class="mm-face mm-back"><img src="${ASSETS.token_acorn}" alt=""></span><span class="mm-face mm-front">${up?img(card.key,''):''}</span></span></button>`}).join('')}</div>
${done?`<div class="mm-win"><h2>Every pair found!</h2><button class="btn btn-primary sc-big" data-act="new-game">Play again</button></div>`:''}</div>`}
function memoryFlip(idx){let g=state.game;if(g.pending||g.matched.includes(idx)||g.revealed.includes(idx)||g.matched.length===16)return;if(g.revealed.length===0){startSpell(()=>revealMemory(idx))}else revealMemory(idx)}
function revealMemory(idx){let g=state.game;g.revealed.push(idx);g.fresh=[idx];if(g.revealed.length===2){g.moves++;let [a,b]=g.revealed;if(g.cards[a].id===g.cards[b].id){g.matched.push(a,b);g.revealed=[];state.notice=g.matched.length===16?'You found every pair!':'You found a matching pair!'}else{g.pending=true;state.notice='Look closely at both pictures…';render();setTimeout(()=>{if(state.screen==='memory'&&state.game===g){g.revealed=[];g.pending=false;state.notice='Try to remember where you saw those pictures.';render()}},1250)}}else state.notice='Now choose a second card.'}
