document.addEventListener('change',e=>{if(e.target.id!=='ad-file')return;const f=e.target.files&&e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{const n=document.getElementById('ad-name');state.adDraft=state.adDraft||{name:'',words:'',for:USERS.slice()};state.adDraft.name=(n&&n.value)||f.name.replace(/\.[^.]+$/,'');state.adDraft.words=adParseWords(r.result).join('\n');state.adMsg='Loaded '+adParseWords(r.result).length+' words from '+f.name+'. Check them, then Save list.';render()};r.readAsText(f)},true);
