document.addEventListener('click',e=>{let btn=e.target.closest('[data-act]');if(!btn)return;let act=btn.dataset.act,id=btn.dataset.idx;if(state.challenge){if(['speak','add-letter','remove-letter','spell-undo','spell-clear','spell-hint','spell-continue'].includes(act)){spellAction(act,id)}return}if(act==='sol-tray'){state.game.trayOpen=!state.game.trayOpen;render();return}if(act==='sol-auto')return solAuto();if(act==='sol-help'){state.game.showHelp=!state.game.showHelp;render();if(state.game.showHelp)say(SOL_SPEECH,'Fox');return}if(act==='set-group'){state.group=btn.dataset.id;save();render();say('Group '+state.group.split('').join(' '));return}if(act==='speak-text'){say(btn.dataset.text);return}if(act==='home'){state.teacher=false;state.screen='home';state.notice='';render();return}if(act==='teacher'){if(state.adult){state.teacher=true;state.adMore=false;render();return}state.adLogin={role:null,pin:''};render();return}if(act==='toggle-volume'){state.volume=!state.volume;save();render();if(state.volume)say('Hello from Spellwood!');return}if(act==='open'){state.teacher=false;setupGame(btn.dataset.id);return}if(act==='new-game'){setupGame(state.screen);return}if(act==='priority'||act==='focus'){state[act]=!state[act];save();render();return}if(act==='reset-progress'){if(confirm('Reset all spelling progress on this device?')){state.attempt={};state.learned={};state.next={};state.completions=0;save();render()}return}if(act==='save-words'){let val=$('word-input').value.split(/[\s,;]+/).map(w=>w.toLowerCase().trim()).filter(w=>/^[a-z]+$/.test(w));if(val.length){GROUPS[state.group]=[...new Set(val)];try{localStorage.setItem('spellwood.customGroups',JSON.stringify(GROUPS))}catch{};state.notice='Word group saved';render()}return}if(act==='restore-words'){if(confirm('Restore the four printed word lists?')){localStorage.removeItem('spellwood.customGroups');location.reload()}return}if(act==='connect-move')return connectMove(Number(id));if(act==='memory-flip')return memoryFlip(Number(id));if(act==='select-item'){state.game.cel=null;state.game.selected=Number(id);render();if(state.screen!=='dam')say(itemInfoText(state.screen,Number(id)),state.screen==='pond'?'Beaver':'Fox');return}if(act==='place-item')return placeItem(Number(id));if(act==='add-pond'){let g=state.game;return startSpell(()=>{const prevWarn=pondAdvice(g).filter(x=>x[0]==='warn').map(x=>x[1]);g.placed.push(POND_ITEMS[g.selected]);g.earned++;const nm=POND_NAMES[g.selected];const newWarn=pondAdvice(g).find(x=>x[0]==='warn'&&!prevWarn.includes(x[1]));const sel=g.selected;g.cel={key:POND_ITEMS[sel],title:nm+' added!',line:POND_FACTS[sel].does,fact:newWarn?newWarn[1]:'',warn:!!newWarn,vis:[],btn:'Add more'};state.notice='';setTimeout(()=>{if(window.playYay)try{playYay()}catch{};say(nm+' added! '+POND_FACTS[sel].does+(newWarn?' '+newWarn[1]:''),'Beaver')},250)})}if(act==='ttt-move')return tttMove(Number(id));if(act==='acorn-drop')return acornDrop(Number(id));if(act==='sol-draw')return solDraw();if(act==='sol-waste'){const gs=state.game;gs.selected=null;const w=gs.waste.at(-1);if(w&&!solAutoMove('waste')){state.notice='No place for '+cardText(w)+' yet. Spell a word to draw a card.';render()}return}if(act==='sol-tableau')return solMoveTableau(Number(btn.dataset.col),Number(id));if(act==='sol-foundation')return solFoundation(btn.dataset.suit)});
document.addEventListener('change',e=>{if(e.target.id==='groups'){state.group=e.target.value;save();render()}if(e.target.id==='seasons'){state.season=e.target.value;save();render()}if(e.target.dataset&&e.target.dataset.voice){const k=e.target.dataset.voice;VOICE_CFG[k]=k==='lift'?Number(e.target.value):e.target.value;saveVoiceCfg();if(k!=='lift'&&neural.status==='ready')neuralPrefetch();return}if(e.target.id==='kt-words'){const v=e.target.value;if(v==='marked'){state.source='marked';state.group='2A'}else{state.source='group';state.group=v.slice(2)}save();render();return}if(e.target.id==='source'){state.source=e.target.value;save();render()}if(e.target.id==='a11y-size'){state.a11y.size=Number(e.target.value);save();render()}if(e.target.id==='a11y-font'){state.a11y.font=e.target.value;save();render()}if(e.target.id==='csv-file'&&e.target.files[0]){e.target.files[0].text().then(importCSV)}});
function importCSV(txt){const rows=txt.split(/\r?\n/).map(r=>r.split(',').map(x=>x.trim().toLowerCase())).filter(r=>r[0]&&/^[a-z]+$/.test(r[0]));if(!rows.length){alert('No words found. Use one word per row, with an optional group name in the second column.');return}const by={};rows.forEach(([w,g])=>{const k=(g||'Imported').toUpperCase();(by[k]=by[k]||[]).push(w)});Object.entries(by).forEach(([k,ws])=>{GROUPS[k]=[...new Set(ws)]});try{localStorage.setItem('spellwood.imported',JSON.stringify(by))}catch{}state.group=Object.keys(by)[0];save();render();alert('Imported '+rows.length+' words.')}
try{const imp=JSON.parse(localStorage.getItem('spellwood.imported'));if(imp)Object.entries(imp).forEach(([k,ws])=>{if(!GROUPS[k])GROUPS[k]=ws})}catch{}
try{const custom=JSON.parse(localStorage.getItem('spellwood.customGroups'));if(custom&&Object.keys(GROUPS).every(g=>Array.isArray(custom[g])&&custom[g].length))Object.assign(GROUPS,custom)}catch{}
